1	package com.maritime.platform.gateway.security;
2	
3	import java.util.ArrayList;
4	import java.util.Collections;
5	import java.util.HashSet;
6	import java.util.List;
7	import java.util.Locale;
8	import java.util.Set;
9	
10	import org.springframework.beans.factory.InitializingBean;
11	import org.springframework.http.server.reactive.ServerHttpRequest;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.util.pattern.PathPattern;
14	import org.springframework.web.util.pattern.PathPatternParser;
15	import org.springframework.web.util.pattern.PatternParseException;
16	
17	@Component
18	public class RouteSecurityPolicyResolver implements InitializingBean {
19	
20		private final GatewaySecurityProperties properties;
21	
22		private final List<GatewaySecurityPolicyCustomizer> customizers;
23	
24		private final List<String> programmaticPublicPaths = new ArrayList<>();
25	
26		private final List<ProgrammaticRouteRule> programmaticRoutes = new ArrayList<>();
27	
28		private List<CompiledPublicPath> compiledPublicPaths = Collections.emptyList();
29	
30		private List<CompiledRouteRule> compiledRoutes = Collections.emptyList();
31	
32		private AuthMode defaultAuthMode;
33	
34		private volatile boolean initialized;
35	
36		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties) {
37			this(properties, Collections.emptyList());
38		}
39	
40		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties,
41		                                   List<GatewaySecurityPolicyCustomizer> customizers) {
42			this.properties = properties;
43			this.customizers = customizers != null ? customizers : Collections.emptyList();
44		}
45	
46		// ---------- programmatic registration (for customizers) ----------
47	
48		public void addPublicPath(String publicPath) {
49			checkNotInitialized();
50			programmaticPublicPaths.add(publicPath);
51		}
52	
53		public void addRoutePolicy(String id, List<String> paths, List<String> methods, AuthMode authMode) {
54			checkNotInitialized();
55			programmaticRoutes.add(new ProgrammaticRouteRule(id, paths, methods, authMode));
56		}
57	
58		// ---------- resolution ----------
59	
60		public RouteSecurityPolicy resolve(ServerHttpRequest request) {
61			return resolve(request.getURI().getPath(), request.getMethod() != null ? request.getMethod().name() : null);
62		}
63	
64		public RouteSecurityPolicy resolve(String path, String httpMethod) {
65			if (!initialized) {
66				compile();
67			}
68			// 1. Public paths take absolute priority — always NONE
69			for (CompiledPublicPath cpp : compiledPublicPaths) {
70				if (cpp.pattern.matches(PathContainerAdapter.parse(path))) {
71					return new RouteSecurityPolicy(AuthMode.NONE, cpp.ruleId);
72				}
73			}
74			// 2. Route policies
75			for (CompiledRouteRule crr : compiledRoutes) {
76				if (crr.matches(path, httpMethod)) {
77					return new RouteSecurityPolicy(crr.authMode, crr.ruleId);
78				}
79			}
80			// 3. Default
81			return new RouteSecurityPolicy(defaultAuthMode, "DEFAULT");
82		}
83	
84		public AuthMode getDefaultAuthMode() {
85			return defaultAuthMode;
86		}
87	
88		// ---------- initialization ----------
89	
90		@Override
91		public void afterPropertiesSet() {
92			compile();
93		}
94	
95		private void compile() {
96			if (initialized) {
97				return;
98			}
99			PathPatternParser parser = new PathPatternParser();
100			parser.setMatchOptionalTrailingSeparator(true);
101	
102			List<CompiledPublicPath> publicPatterns = new ArrayList<>();
103			List<CompiledRouteRule> routeRules = new ArrayList<>();
104	
105			// Apply customizers to collect programmatic registrations
106			for (GatewaySecurityPolicyCustomizer customizer : customizers) {
107				customizer.customize(this);
108			}
109	
110			// Compile public paths from properties
111			for (String path : properties.getPublicPaths()) {
112				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC:" + path));
113			}
114			// Compile programmatic public paths
115			for (String path : programmaticPublicPaths) {
116				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC(custom):" + path));
117			}
118	
119			// Compile route policies from properties
120			for (GatewaySecurityProperties.RoutePolicy rp : properties.getRoutes()) {
121				Set<String> methods = uppercaseSet(rp.getMethods());
122				for (String path : rp.getPaths()) {
123					routeRules.add(new CompiledRouteRule(
124							compilePattern(parser, path), rp.getId(), methods, rp.getAuthMode()));
125				}
126			}
127			// Compile programmatic route policies
128			for (ProgrammaticRouteRule pr : programmaticRoutes) {
129				Set<String> methods = uppercaseSet(pr.methods);
130				for (String path : pr.paths) {
131					routeRules.add(new CompiledRouteRule(
132							compilePattern(parser, path), pr.id, methods, pr.authMode));
133				}
134			}
135	
136			this.compiledPublicPaths = Collections.unmodifiableList(publicPatterns);
137			this.compiledRoutes = Collections.unmodifiableList(routeRules);
138			this.defaultAuthMode = properties.getDefaultAuthMode();
139			this.initialized = true;
140		}
141	
142		private static PathPattern compilePattern(PathPatternParser parser, String pattern) {
143			try {
144				return parser.parse(pattern);
145			} catch (PatternParseException e) {
146				throw new IllegalStateException("Invalid path pattern '" + pattern + "': " + e.getMessage(), e);
147			}
148		}
149	
150		private static Set<String> uppercaseSet(List<String> values) {
151			if (values == null || values.isEmpty()) {
152				return Collections.emptySet();
153			}
154			Set<String> set = new HashSet<>(values.size());
155			for (String v : values) {
156				if (v != null && !v.isBlank()) {
157					set.add(v.strip().toUpperCase(Locale.ROOT));
158				}
159			}
160			return Collections.unmodifiableSet(set);
161		}
162	
163		private void checkNotInitialized() {
164			if (initialized) {
165				throw new IllegalStateException(
166						"RouteSecurityPolicyResolver is already initialized. " +
167						"addPublicPath / addRoutePolicy must be called from a GatewaySecurityPolicyCustomizer.");
168			}
169		}
170	
171		// ---------- internal types ----------
172	
173		private static class CompiledPublicPath {
174			final PathPattern pattern;
175			final String ruleId;
176	
177			CompiledPublicPath(PathPattern pattern, String ruleId) {
178				this.pattern = pattern;
179				this.ruleId = ruleId;
180			}
181		}
182	
183		private static class CompiledRouteRule {
184			final PathPattern pattern;
185			final String ruleId;
186			final Set<String> methods;
187			final AuthMode authMode;
188	
189			CompiledRouteRule(PathPattern pattern, String ruleId, Set<String> methods, AuthMode authMode) {
190				this.pattern = pattern;
191				this.ruleId = ruleId;
192				this.methods = methods;
193				this.authMode = authMode;
194			}
195	
196			boolean matches(String path, String httpMethod) {
197				if (!this.pattern.matches(PathContainerAdapter.parse(path))) {
198					return false;
199				}
200				if (methods.isEmpty()) {
201					return true;
202				}
203				if (httpMethod == null) {
204					return false;
205				}
206				return methods.contains(httpMethod.toUpperCase(Locale.ROOT));
207			}
208		}
209	
210		private static class ProgrammaticRouteRule {
211			final String id;
212			final List<String> paths;
213			final List<String> methods;
214			final AuthMode authMode;
215	
216			ProgrammaticRouteRule(String id, List<String> paths, List<String> methods, AuthMode authMode) {
217				this.id = id;
218				this.paths = paths != null ? paths : Collections.emptyList();
219				this.methods = methods != null ? methods : Collections.emptyList();
220				this.authMode = authMode;
221			}
222		}
223	
224		/**
225		/**
226		 * Adapter that bridges a string path to {@link org.springframework.http.server.PathContainer}
227		 * without requiring the spring-web dependency at the API level.
228		 */
229		private static final class PathContainerAdapter {
230			private PathContainerAdapter() {}
231	
232			static org.springframework.http.server.PathContainer parse(String path) {
233				return org.springframework.http.server.PathContainer.parsePath(path);
234			}
235		}
236	}
