@Order(GatewayFilterOrder.UNTRUSTED_HEADER_STRIP)
public class UntrustedHeaderStripFilter implements GlobalFilter {

    // Headers that clients should never set directly - they must be set by the gateway
    private static final Set<String> UNTRUSTED_HEADERS = Set.of(
        "X-Internal-Call",
        "X-User-Id", "X-User-Name",
        "X-Active-Org-Code", "X-Active-Org-Name",
        "X-Session-Id",
        "X-System-Scope",
        "X-User-Source",
        "X-Tenant-Id", "X-Tenant-Code",
        "X-App-Key", "X-App-Code", "X-App-Id",
        "X-Verified-App-Code",
        "X-App-Permissions",
        "X-Trace-Id"
    );

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        ServerHttpRequest request = exchange.getRequest();
        ServerHttpRequest mutated = request.mutate()
            .headers(headers -> UNTRUSTED_HEADERS.forEach(headers::remove))
            .build();
        return chain.filter(exchange.mutate().request(mutated).build());
    }
}
