		void requestLogOrder() {
			Order ann = AnnotationUtils.findAnnotation(RequestLogGatewayFilter.class, Order.class);
			assertThat(ann).isNotNull();
			assertThat(ann.value()).isEqualTo(GatewayFilterOrder.REQUEST_LOG);
		}

