		void policyRuleId() {
			GatewaySecurityProperties props = new GatewaySecurityProperties();
			props.getPublicPaths().add("/actuator/**");
			RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props);
			resolver.afterPropertiesSet();

